select throws_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id": "eeeeeeee-0000-4000-8000-000000000201", "action": "replacement", "observed_at": "2020-01-03T00:00:00Z", "physical": "150"}'::jsonb)$$, '55000', null, 'Archived vehicle rejects replacement');
select throws_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id": "eeeeeeee-0000-4000-8000-000000000201", "action": "correct", "observed_at": "2020-01-03T00:00:00Z", "physical": "150"}'::jsonb)$$, '55000', null, 'Archived vehicle rejects correct');
select throws_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id": "eeeeeeee-0000-4000-8000-000000000201", "action": "void", "observed_at": "2020-01-03T00:00:00Z", "physical": "150"}'::jsonb)$$, '55000', null, 'Archived vehicle rejects void');
select is((select accumulated::numeric from public.meter_history('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001') where not voided order by observed_at desc limit 1), 660::numeric, 'Archived vehicle retains its history');
reset role;
update public.memberships set status='revoked' where organization_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' and user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select set_config('request.jwt.claims', '{"sub": "11111111-1111-4111-8111-111111111111", "role": "authenticated", "organization_id": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}', true);
select throws_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id": "eeeeeeee-0000-4000-8000-000000000201", "action": "reading", "observed_at": "2020-01-03T00:00:00Z", "physical": "150"}'::jsonb)$$, '42501', null, 'Revocation applies with unchanged JWT');
select is((select count(*) from public.meter_history('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001')),0::bigint,'Revocation immediately hides history');
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select public.record_meter_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-0000-4000-8000-000000000001','{"command_id": "eeeeeeee-0000-4000-8000-000000000201", "action": "reading", "observed_at": "2020-01-03T00:00:00Z", "physical": "150"}'::jsonb)$$, '42501', null, 'Missing identity cannot write');
reset role;
select * from finish();
rollback;
